from pathlib import Path
import pandas as pd
import numpy as np

def f(v,n=3):return 'NA' if pd.isna(v) else f'{float(v):.{n}f}'
def md(headers,rows):
    return '\n'.join(['| '+' | '.join(headers)+' |','| '+' | '.join(['---']*len(headers))+' |']+['| '+' | '.join(map(str,r))+' |' for r in rows])
def build_reports(root,results):
    sections=[]
    if 1 in results:
        t=results[1];a=t.set_index('model').loc['OneFactor'];b=t.set_index('model').loc['FourFactor']
        tab=md(['Модель','CFI scaled','TLI scaled','RMSEA scaled [90% CI]','SRMR','Жинақталды','Жарамды'],[[r.model,f(r.CFI_scaled),f(r.TLI_scaled),f'{f(r.RMSEA_scaled)} [{f(r.RMSEA90_low_scaled)}; {f(r.RMSEA90_high_scaled)}]',f(r.SRMR),str(r.converged),str(r.admissible)] for _,r in t.iterrows()])
        robust=md(['Модель','CFI robust','TLI robust','RMSEA robust [90% CI]'],[[r.model,f(r.CFI_robust),f(r.TLI_robust),f'{f(r.RMSEA_robust)} [{f(r.RMSEA90_low_robust)}; {f(r.RMSEA90_high_robust)}]'] for _,r in t.iterrows()])
        if a.admissible and b.admissible:
            finding=f"Екі модель де жинақталды және параметрлік жарамдылық тексеруінен өтті. Төрт факторлы модельдің CFI айырмасы {f(b.CFI_scaled-a.CFI_scaled,4)}, RMSEA айырмасы {f(b.RMSEA_scaled-a.RMSEA_scaled,4)}, SRMR айырмасы {f(b.SRMR-a.SRMR,4)}. Ең үлкен абсолюттік фактор корреляциясы {f(b.max_abs_latent_correlation)}. Fit артықшылығы өлшемдердің дискриминанттық валидтілігін өздігінен дәлелдемейді."
        else:
            bad=', '.join(t.loc[~t.admissible.astype(bool),'model'])
            finding=f"Жинақталу параметрлік жарамдылыққа тең емес. Жарамсыз шешім: {bad}. Fit индекстері тек диагностика үшін сақталған; оларды құрылым расталды деген дәлел ретінде пайдалануға болмайды. Төрт фактордағы ең үлкен абсолюттік корреляция {f(b.max_abs_latent_correlation)}."
        text='\n\n'.join(['# Эксперимент 1 Ordinal CFA',
          '## Мақсаты','Бір жалпы факторды және теориялық D1–D4 төрт корреляцияланған факторды салыстыру.',
          '## Әдіс және деректер','Бастапқы CSV-ден қайта алынған 159 ересек, 14 ordinal сұрақ, бес жауап категориясы. R/lavaan cfa(..., ordered=Q01:Q14, estimator="WLSMV", parameterization="delta", std.lv=TRUE). Бағалау DWLS, бірақ стандарттық қателер мен χ² статистикасына mean/variance түзетуі қолданылады; бұл жай WLS не ML емес. Негізгі кестеде scaled/shifted тестке негізделген CFI/TLI/RMSEA және RMSEA 90% CI берілді. Lavaan-ның қосымша robust көрсеткіштері CSV-де бөлек сақталған; олар scaled көрсеткіштермен араластырылмайды. Фактор дисперсиялары 1-ге бекітілді; төрт фактордың өзара корреляциялары еркін бағаланды. Қосалқы жүктемелер, корреляцияланған қалдықтар немесе modification index арқылы post-hoc өзгеріс қосылған жоқ.',
          '## Нәтижелер',tab,'Lavaan robust индекстері бөлек бағалау ретінде төменде берілген; scaled және robust нұсқалары бір көрсеткіш емес.',robust,finding,
          f"Төрт факторлы модельде салыстырмалы сәйкестік жақсырақ болғанымен, RMSEA scaled={f(b.RMSEA_scaled)}, robust={f(b.RMSEA_robust)}; бір факторлы модельде тиісінше {f(a.RMSEA_scaled)} және {f(a.RMSEA_robust)}. Сондықтан бір факторды барлық ковариацияны жеткілікті сипаттайды деп те, төрт теориялық факторды түпкілікті расталды деп те көрсетуге болмайды. Бір жалпы фактордың басымдығы туралы EFA/PA қорытындысы қатаң бір факторлы CFA моделінің жақсы fit көрсетуіне тең емес.",
          f"Бір факторлы модель: scaled χ²({int(a.df_scaled)})={f(a.chisq_scaled,2)}; төрт факторлы модель: scaled χ²({int(b.df_scaled)})={f(b.chisq_scaled,2)}. WLSMV χ² мәндері жай шегеріліп, айырма тесті ретінде қолданылған жоқ. Теріс қалдық дисперсиялары тиісінше {int(a.negative_residual_variances)} және {int(b.negative_residual_variances)}; |стандартталған жүктеме|>1 саны {int(a.standardized_loadings_gt1)} және {int(b.standardized_loadings_gt1)}.",
          '## Ғылыми түсіндірме және шектеулер','Бұрынғы EFA және параллель талдау бір басым факторды көрсетті. CFA көрсеткіштері сол нәтижені модель шектеулері арқылы толықтырады; бір басым фактор төрт мазмұндық бағыттың бірдей екенін де, бір факторлы модель барлық ковариацияны дәл түсіндіретінін де білдірмейді. Төрт факторлы модельдің fit жақсаруы оның еркіндігі көбірек болуына байланысты болуы мүмкін. Факторлар корреляциялары, жүктемелер, Heywood жағдайлары және бірнеше fit көрсеткіші бірге бағалануы керек. Бұл CFA EFA жүргізілген сол 159 қатысушыға негізделген, тәуелсіз валидация емес. Шағын іріктеме, бес деңгейлі жауаптар және сирек ұяшықтар ordinal бағалардың белгісіздігін арттырады. Үлкен тәуелсіз іріктемеде қайталау қажет.',
          'Әдіс дереккөзі: [lavaan categorical data](https://lavaan.ugent.be/tutorial/cat.html).'])
        (root/'EXP01_Ordinal_CFA/report.md').write_text(text,encoding='utf-8');sections.append(text)
    if 2 in results:
        t=results[2];worst=t.loc[t.jaccard.idxmin()]
        tab=md(['Әдістер','Бюджет','K','ρ','τb','Jaccard','Ортақ n','Ортақ %','Орташа |Δrank|','max |Δrank|'],[[r.method1+'–'+r.method2,str(int(r.budget_percent))+'%',int(r.K),f(r.spearman,4),f(r.kendall_tau_b,4),f(r.jaccard,4),int(r.overlap_n),f(r.overlap_percent,2),f(r.mean_abs_rank_change,2),f(r.max_abs_rank_change,1)] for _,r in t.iterrows()])
        same=bool(t.overlap_n.eq(t.K).all())
        text='\n\n'.join(['# Эксперимент 2 Top-K таңдау тұрақтылығы',
          '## Мақсаты','Үш әдіс ең төмен балл алған бірдей студенттерді таңдай ма және айырмашылық бюджетке тәуелді ме?',
          '## Әдіс және деректер','159 ересек; M1 — D1–D4 өлшемдерінің тең орташа мәні, M2 — 14 сұрақтың орташа мәні, M3 — бұрынғы бір факторлы Pearson MINRES regression score ZR⁻¹λ. Бұрынғы M3 коэффициенттері мен баллдары сандық тексерілді. Ең төмен балл бірінші; K=ceil(p×159): 16, 32, 48. Top-K тең баллдары бастапқы техникалық ID-дің лексикографиялық ретімен шешілді. Жарияланатын нәтижеде P001… талдау кодтары ғана көрсетілді. Корреляциялар және ранг айырмалары орташа рангтарды пайдаланады. Тек машина дәлдігіндегі айырмашылықтарды жою үшін салыстыру кілті 10 ондыққа дөңгелектелді; экспортталған баллдар өзгертілмеді. M1/M2 нақты балл аралығы бұл дәлдіктен әлдеқайда үлкен. Шекарадағы тең баллдар cutoff_ties.csv файлында көрсетілген.',
          'Jaccard=intersection/union; overlap%=100×intersection/K. Бұл пайыз Jaccard×100 емес. Spearman/Kendall және ранг өзгерісі толық 159 адамға есептелді, сондықтан үш бюджетте қайталанады.',
          '## Нәтижелер',tab,
          ('Барлық әдіс пен бюджетте таңдалған жиындар бірдей.' if same else 'Әдістер барлық бюджетте бірдей студенттерді таңдамайды.'),
          f"Ең төмен Jaccard: {worst.method1}–{worst.method2}, {int(worst.budget_percent)}% бюджет, K={int(worst.K)}; J={f(worst.jaccard,4)}, ортақ {int(worst.overlap_n)} студент ({f(worst.overlap_percent,2)}%). Бірдей минималды мән бірнеше салыстыруда кездессе, кестеде олардың бәрі берілген.",
          '## Ғылыми түсіндірме және шектеулер','Жалпы рейтинг корреляциясының жоғары болуы Top-K жиындарының толық сәйкестігін қамтамасыз етпейді. Бюджет шегіндегі шағын ранг өзгерісі таңдауды өзгерте алады; tied-cutoff жағдайында техникалық ID арқылы шешу қайталанымдылық береді, бірақ студенттің тәуекелін ажырататын ғылыми дәлел емес. Бұл эксперимент нақты киберқауіпсіздік оқиғаларын болжауды немесе скрининг сезімталдығын бағаламайды. M1 бастапқы әдіс болып қалады; оның оңтайлылығы дәлелденбейді.'])
        (root/'EXP02_TopK_Stability/report.md').write_text(text,encoding='utf-8');sections.append(text)
    if 3 in results:
        t=results[3];o=pd.read_csv(root/'EXP03_Quality_Sensitivity/flag_overlaps.csv');impact=t.iloc[1:].loc[t.iloc[1:].BDSF_mean_delta_vs_S0.abs().idxmax()]
        tab=md(['Сценарий','n','M','Медиана','SD','α','ω','KMO','Bartlett χ²','PA','ΔM'],[[r.scenario,int(r.n),f(r.BDSF_mean,2),f(r.BDSF_median,2),f(r.BDSF_sd,2),f(r.alpha),f(r.omega_raw_sum),f(r.KMO),f(r.Bartlett_chi2,2),int(r.parallel_retained_factors),f(r.BDSF_mean_delta_vs_S0,2)] for _,r in t.iterrows()])
        overlaps=md(['Белгі 1','Белгі 2','1 саны','2 саны','Қабаттасу','Бірдей жиын'],[[r.flag1,r.flag2,int(r.flag1_n),int(r.flag2_n),int(r.intersection_n),r.identical_sets] for _,r in o.iterrows()])
        text='\n\n'.join(['# Эксперимент 3 Сапа жалаушаларының жеке әсері',
          '## Мақсаты','Сапа белгілерін жеке және бірге сүзу негізгі статистикаға қаншалықты әсер ететінін тексеру.',
          '## Әдіс және деректер','S0 — барлық 159 ересек. S1 — DUPLICATE_RESPONSE_PATTERN жоқ; S2 — DUPLICATE_TIMESTAMP жоқ; S3 — STRAIGHTLINE_ALL_14 жоқ; S4 — ешбір жалаушасы жоқ. Белгілер бастапқы кодтағыдай барлық 180 жауапта бағаланады, кейін ересектер бөлінеді. Бастапқы кәмелетке толмаған 21 адам барлық сценарийге кірмейді. Орташа/медиана/SD M1 бойынша, raw Cronbach α және бір факторлы MINRES congeneric ω 14 сұрақтың тең қосындысына қатысты. ω бастапқы 25% M1 композитінің сенімділігімен тікелей теңестірілмейді. Pearson KMO, Bartlett және 500 Gaussian correlation matrix негізіндегі parallel analysis, бастапқы seed=20261030. Бірдей жазбалар жиынына бірдей есептеу қайта орындалмайды. S1=S3 болса, S3 параллель талдауы S1-мен бірдей.',
          '## Нәтижелер',tab,overlaps,
          f"M1 орташа мәніне ең үлкен абсолюттік әсер {impact.scenario}: ΔM={f(impact.BDSF_mean_delta_vs_S0,2)} ({f(impact.BDSF_mean_relative_percent_vs_S0,2)}%). α диапазоны {f(t.alpha.min())}–{f(t.alpha.max())}, ω {f(t.omega_raw_sum.min())}–{f(t.omega_raw_sum.max())}. Параллель талдаудағы фактор сандары: "+', '.join(f'{r.scenario}={int(r.parallel_retained_factors)}' for _,r in t.iterrows())+'.',
          'Жеке критерийлерді салыстырғанда S1 және S3 толық бірдей жиын береді: 18 жауап. Сондықтан олардың әсерін бір-бірінен ажырату мүмкін емес. Уақыт белгісіне қатысты S2 тек екі жауапты алып тастайды және орташа баллға әсері әлдеқайда аз. Барлық сценарийде бір басым фактор сақталды; алайда S1/S3/S4 жағдайларында ішкі келісімділік S0-ден төмендеді. Негізгі ғылыми қорытынды сақталғанымен, сенімділік коэффициентінің деңгейі жалаушалы жауаптарға сезімтал.',
          '## Ғылыми түсіндірме және шектеулер','Сапа жалаушасы жауаптың жалған не жарамсыз екенін дәлелдемейді. Уақыт белгісінің қайталануы бір адамның бірнеше рет қатысқанын дәлелдемейді. Бірдей жауап үлгісі мен straightlining толық қабаттасса, олардың әсерін екі дербес механизм ретінде түсіндіруге болмайды. S1–S4 — S0 ішкі жиындары; тәуелсіз топ тесттері қолданылмайды. Орташа мән аз өзгерсе де α/ω төмендеуі мүмкін; осы екі қорытынды бөлек бағаланады. Негізгі S0 іріктемесі сақталады.'])
        (root/'EXP03_Quality_Sensitivity/report.md').write_text(text,encoding='utf-8');sections.append(text)
    if len(results)==3:
        text='# BDSF жобасының 17 бөлімі бойынша ғылыми есеп\n\nҮш қосымша эксперимент бастапқы екі CSV-ден есептелді. Алдыңғы нәтижелер мен M1 өзгертілмеді. Бұл сол іріктемені қайта талдау, тәуелсіз валидация емес.\n\n'+'\n\n---\n\n'.join(sections)
        text+='\n\n## Мақалаға енгізу\n\n1. CFA әдісі мен екі модельдің кестесі — құрылымдық валидтілік бөліміне. Жарамсыз модель болса, оның жақсы fit индексі қолдау ретінде берілмейді.\n2. Top-K кестесі — есептеу алгоритмінің тұрақтылығы бөліміне.\n3. S0–S4 кестесі — деректер сапасына сезімталдық бөліміне.\nБастапқы мақала файлы өзгертілген жоқ.\n'
        (root/'FINAL_Q3_REPORT.md').write_text(text,encoding='utf-8')
